const cb=$json.callback_query||null; const msg=$json.message||$json.edited_message||null;
if(msg){const text=String(msg.text||'').trim();const chat=msg.chat?.id||'';const actor=String(msg.from?.id||'manager');if(text.toLowerCase()==='/health')return[{json:{route:'health',actor_id:actor,channel:'telegram',telegram_chat_id:chat}}];if(text)return[{json:{route:'action',action:'EDIT',queue_id:0,edited_text:text,actor_id:actor,channel:'telegram',telegram_chat_id:chat,reply_to_message_id:Number(msg.reply_to_message?.message_id||0)}}];return[{json:{route:'ignore',telegram_chat_id:chat}}];}
if(!cb)return[{json:{route:'ignore'}}];const p=String(cb.data||'').split(':');const action=String(p[0]||'').toUpperCase();const id=Number(p[1]||0);const base={actor_id:String(cb.from?.id||'manager'),channel:'telegram',telegram_chat_id:cb.message?.chat?.id||'',telegram_callback_query_id:cb.id};
if(action==='DONE')return[{json:{...base,route:'complete',stage_id:id}}];if(['SEND','SEND_EMAIL','SEND_TELEGRAM','SEND_BOTH','EDIT','HOLD','RETRY_EMAIL','RETRY_TELEGRAM'].includes(action))return[{json:{...base,route:'action',action,queue_id:id}}];if(['SKIP','SNOOZE','CHASE'].includes(action))return[{json:{...base,route:'action',action,stage_id:id}}];if(action==='CANCEL')return[{json:{...base,route:'action',action,turn_id:id}}];return[{json:{...base,route:'ignore'}}];

const rows = $input.all().map(item => item.json);
const now = new Date();
function parseStages(value) { if (Array.isArray(value)) return value; if (!value) return []; try { return JSON.parse(value); } catch { return []; } }
function hoursSince(value) { if (!value) return 0; return Math.max(0, (now.getTime() - new Date(value).getTime()) / 36e5); }
function healthFor(hours, slaHours, status) { if (status === 'awaiting_approval') return 'amber'; const sla = Number(slaHours || 0); if (sla <= 0) return 'green'; if (hours / sla >= 1) return 'red'; if (hours / sla >= 0.5) return 'amber'; return 'green'; }
const rank = { red: 3, amber: 2, green: 1 };
const turns = rows.map(row => {
  const hours = hoursSince(row.current_activated_at);
  const moveout = new Date(String(row.moveout_date).slice(0, 10) + 'T00:00:00Z');
  const today = new Date(now.toISOString().slice(0, 10) + 'T00:00:00Z');
  return {
    stage_id: Number(row.current_stage_id),
    turn_id: Number(row.turn_id),
    unit_label: row.unit_label,
    display_label: String(row.unit_label) + ' ' + String(row.property_address || '').split(' ').slice(1).join(' ').trim(),
    current_stage_name: row.current_stage_name,
    current_vendor_name: row.current_vendor_name || 'Unassigned',
    hours_at_stage: Math.round(hours * 10) / 10,
    health: healthFor(hours, row.current_sla_hours, row.current_stage_status),
    dollars_burned: Math.round((Number(row.rent_monthly || 0) / 30) * Math.max(0, Math.floor((today - moveout) / 864e5))),
    stages: parseStages(row.stages)
  };
}).sort((a, b) => (rank[b.health] - rank[a.health]) || (b.hours_at_stage - a.hours_at_stage));
const activeCount = turns.length;
const dollars = turns.reduce((sum, turn) => sum + turn.dollars_burned, 0);
const vendorReply = rows[0] ? Number(rows[0].vendor_reply_rate || 0) : 0;
const autoHandled = rows[0] ? Number(rows[0].auto_handled_rate || 0) : 0;
const lines = turns.map((turn, index) => {
  const age = turn.hours_at_stage >= 24 ? (Math.round((turn.hours_at_stage / 24) * 10) / 10) + 'd' : turn.hours_at_stage + 'h';
  return (index + 1) + '. ' + turn.display_label + ' - ' + turn.current_stage_name + ' - ' + age + ' - $' + turn.dollars_burned + ' burned';
});
const first = turns[0] || {};
const second = turns[1] || {};
// Demo digest exposes only Done and Chase. Skip, Snooze and Cancel remain supported by the
// manager action core and its callback data; they are simply not surfaced as digest buttons.
const third = turns[2] || {};
const pair = (t) => [
  { text: t.stage_id ? 'Done: ' + t.unit_label + ' ' + t.current_stage_name : '-', callback_data: t.stage_id ? 'DONE:' + t.stage_id : 'NOOP' },
  { text: t.stage_id ? 'Chase: ' + t.unit_label + ' ' + t.current_stage_name : '-', callback_data: t.stage_id ? 'CHASE:' + t.stage_id : 'NOOP' }
];
const buttons = [].concat(pair(first), pair(second), pair(third));
return [{ json: {
  chat_id: 'stage3-manager-chat-id-missing',
  digest_text: 'Daily make-ready digest\n' + activeCount + ' units in turn - $' + dollars + ' burning right now\nVendor reply rate ' + vendorReply + '% - Auto-handled ' + autoHandled + '% (30 days)\n\n' + lines.join('\n'),
  buttons
} }];
